export const OPENAPI_YAML = "openapi: 3.1.0\ninfo:\n  title: Monday Night Sports — Backend API\n  version: 0.4.0\n  description: |\n    Supabase Edge Functions backing Monday Night Sports.\n\n    - Public reads: `fixtures-public`, `live`, `results-public`, `standings`.\n    - Organiser writes (Supabase Auth JWT): `seasons`, `teams`,\n      `match-access`, `sport-configs`.\n    - Scoped scoring writes (operator match code): `scoring/:fixtureId/*`.\n\n    Base path for every function is `/functions/v1/<function-name>`.\n\n    Realtime subscription details for live scores live in\n    `docs/realtime.md`.\n  contact:\n    name: Monday Night Sports (COSA)\n  license:\n    name: MIT\n\nservers:\n  - url: http://127.0.0.1:54321/functions/v1\n    description: Local Supabase stack (default port 54321)\n  - url: https://{ref}.functions.supabase.co\n    description: Hosted Supabase project\n    variables:\n      ref:\n        default: your-project-ref\n        description: Your Supabase project reference\n\ntags:\n  - name: public\n    description: Unauthenticated read endpoints\n  - name: seasons\n    description: Organiser season management\n  - name: teams\n    description: Organiser team management\n  - name: sport-configs\n    description: Organiser sport-config CRUD\n  - name: scoring\n    description: Live scoring writes (match-code gated)\n  - name: match-access\n    description: Mint and revoke scoped operator match codes (organiser)\n  - name: live\n    description: Public live-score endpoint\n  - name: standings\n    description: Public standings, grouped by sport\n  - name: results-public\n    description: Public archive of past events + results\n  - name: docs\n    description: Interactive API documentation\n\nsecurity:\n  - organiserBearer: []\n\npaths:\n  # ----------------------------------------------------------------\n  # fixtures-public\n  # ----------------------------------------------------------------\n  /fixtures-public:\n    get:\n      tags: [public]\n      summary: Public draw for a published event\n      description: |\n        Renders a single event's draw as HTML (default), plain text\n        (`format=text`) or JSON (`format=json`). RLS gates the underlying\n        tables — unpublished events return 404.\n\n        Sprint C addition: the response surfaces `fixtures.status`\n        (scheduled / live / complete / cancelled) and, for live and\n        complete fixtures, the current score (from `fixture_live_state`\n        or `results`).\n      security: []\n      parameters:\n        - name: event\n          in: query\n          required: true\n          schema: { type: string, format: uuid }\n        - name: format\n          in: query\n          required: false\n          schema:\n            type: string\n            enum: [html, text, json]\n            default: html\n      responses:\n        '200':\n          description: OK\n          content:\n            text/html:\n              schema: { type: string }\n            text/plain:\n              schema: { type: string }\n            application/json:\n              schema:\n                type: object\n                properties:\n                  event: { $ref: '#/components/schemas/Event' }\n                  fixtures:\n                    type: array\n                    items: { $ref: '#/components/schemas/PublicFixture' }\n        '400': { $ref: '#/components/responses/BadRequest' }\n        '404': { $ref: '#/components/responses/NotFound' }\n\n  # ----------------------------------------------------------------\n  # seasons\n  # ----------------------------------------------------------------\n  /seasons:\n    get:\n      tags: [seasons]\n      summary: List seasons (organiser view)\n      responses:\n        '200':\n          description: OK\n          content:\n            application/json:\n              schema:\n                type: object\n                properties:\n                  seasons:\n                    type: array\n                    items: { $ref: '#/components/schemas/Season' }\n        '401': { $ref: '#/components/responses/Unauthorized' }\n    post:\n      tags: [seasons]\n      summary: Create a season\n      requestBody:\n        required: true\n        content:\n          application/json:\n            schema: { $ref: '#/components/schemas/CreateSeasonBody' }\n      responses:\n        '201':\n          description: Created\n          content:\n            application/json:\n              schema:\n                type: object\n                properties:\n                  season: { $ref: '#/components/schemas/Season' }\n        '400': { $ref: '#/components/responses/BadRequest' }\n        '401': { $ref: '#/components/responses/Unauthorized' }\n\n  /seasons/{id}:\n    parameters:\n      - $ref: '#/components/parameters/UuidPath'\n    get:\n      tags: [seasons]\n      summary: Get one season\n      responses:\n        '200':\n          description: OK\n          content:\n            application/json:\n              schema:\n                type: object\n                properties:\n                  season: { $ref: '#/components/schemas/Season' }\n        '404': { $ref: '#/components/responses/NotFound' }\n    patch:\n      tags: [seasons]\n      summary: Update a season (sparse)\n      requestBody:\n        required: true\n        content:\n          application/json:\n            schema: { $ref: '#/components/schemas/UpdateSeasonBody' }\n      responses:\n        '200':\n          description: OK\n          content:\n            application/json:\n              schema:\n                type: object\n                properties:\n                  season: { $ref: '#/components/schemas/Season' }\n        '400': { $ref: '#/components/responses/BadRequest' }\n        '404': { $ref: '#/components/responses/NotFound' }\n\n  /seasons/{id}/activate:\n    parameters:\n      - $ref: '#/components/parameters/UuidPath'\n    post:\n      tags: [seasons]\n      summary: Mark this season active (unsets any other active)\n      responses:\n        '200': { description: OK }\n        '400': { $ref: '#/components/responses/BadRequest' }\n        '404': { $ref: '#/components/responses/NotFound' }\n\n  /seasons/{id}/archive:\n    parameters:\n      - $ref: '#/components/parameters/UuidPath'\n    post:\n      tags: [seasons]\n      summary: Archive a season (soft-delete; clears is_active)\n      responses:\n        '200': { description: OK }\n        '404': { $ref: '#/components/responses/NotFound' }\n\n  # ----------------------------------------------------------------\n  # teams\n  # ----------------------------------------------------------------\n  /teams:\n    get:\n      tags: [teams]\n      summary: List teams for a season\n      parameters:\n        - name: season\n          in: query\n          required: true\n          schema: { type: string, format: uuid }\n      responses:\n        '200':\n          description: OK\n          content:\n            application/json:\n              schema:\n                type: object\n                properties:\n                  teams:\n                    type: array\n                    items: { $ref: '#/components/schemas/Team' }\n        '400': { $ref: '#/components/responses/BadRequest' }\n    post:\n      tags: [teams]\n      summary: Create a team in a season\n      requestBody:\n        required: true\n        content:\n          application/json:\n            schema: { $ref: '#/components/schemas/CreateTeamBody' }\n      responses:\n        '201':\n          description: Created\n          content:\n            application/json:\n              schema:\n                type: object\n                properties:\n                  team: { $ref: '#/components/schemas/Team' }\n        '400': { $ref: '#/components/responses/BadRequest' }\n        '409': { $ref: '#/components/responses/Conflict' }\n\n  /teams/{id}:\n    parameters:\n      - $ref: '#/components/parameters/UuidPath'\n    patch:\n      tags: [teams]\n      summary: Rename a team\n      requestBody:\n        required: true\n        content:\n          application/json:\n            schema:\n              type: object\n              required: [name]\n              properties:\n                name: { type: string }\n      responses:\n        '200': { description: OK }\n        '400': { $ref: '#/components/responses/BadRequest' }\n        '404': { $ref: '#/components/responses/NotFound' }\n        '409': { $ref: '#/components/responses/Conflict' }\n    delete:\n      tags: [teams]\n      summary: Remove a team\n      responses:\n        '200': { description: OK }\n        '404': { $ref: '#/components/responses/NotFound' }\n\n  /teams/bulk:\n    post:\n      tags: [teams]\n      summary: Bulk-add teams from a pasted list\n      requestBody:\n        required: true\n        content:\n          application/json:\n            schema:\n              type: object\n              required: [season_id, names]\n              properties:\n                season_id: { type: string, format: uuid }\n                names:\n                  type: array\n                  items: { type: string }\n      responses:\n        '201':\n          description: Created\n          content:\n            application/json:\n              schema:\n                type: object\n                properties:\n                  inserted:\n                    type: array\n                    items: { $ref: '#/components/schemas/Team' }\n                  skipped_duplicates_in_input:\n                    type: array\n                    items: { type: string }\n                  skipped_existing_in_season:\n                    type: array\n                    items: { type: string }\n        '400': { $ref: '#/components/responses/BadRequest' }\n\n  # ----------------------------------------------------------------\n  # sport-configs\n  # ----------------------------------------------------------------\n  /sport-configs:\n    get:\n      tags: [sport-configs]\n      summary: List sport configs for a season\n      parameters:\n        - name: season\n          in: query\n          required: true\n          schema: { type: string, format: uuid }\n      responses:\n        '200':\n          description: OK\n          content:\n            application/json:\n              schema:\n                type: object\n                properties:\n                  sport_configs:\n                    type: array\n                    items: { $ref: '#/components/schemas/SportConfigRow' }\n        '400': { $ref: '#/components/responses/BadRequest' }\n    post:\n      tags: [sport-configs]\n      summary: Upsert a sport config on (season_id, sport)\n      requestBody:\n        required: true\n        content:\n          application/json:\n            schema: { $ref: '#/components/schemas/UpsertSportConfigBody' }\n      responses:\n        '201':\n          description: Created (or updated)\n          content:\n            application/json:\n              schema:\n                type: object\n                properties:\n                  sport_config: { $ref: '#/components/schemas/SportConfigRow' }\n        '400': { $ref: '#/components/responses/BadRequest' }\n        '401': { $ref: '#/components/responses/Unauthorized' }\n\n  /sport-configs/{id}:\n    parameters:\n      - $ref: '#/components/parameters/UuidPath'\n    patch:\n      tags: [sport-configs]\n      summary: Partial update of a sport config\n      requestBody:\n        required: true\n        content:\n          application/json:\n            schema:\n              type: object\n              properties:\n                sport: { type: string }\n                config: { $ref: '#/components/schemas/SportConfig' }\n      responses:\n        '200':\n          description: OK\n          content:\n            application/json:\n              schema:\n                type: object\n                properties:\n                  sport_config: { $ref: '#/components/schemas/SportConfigRow' }\n        '400': { $ref: '#/components/responses/BadRequest' }\n        '404': { $ref: '#/components/responses/NotFound' }\n    delete:\n      tags: [sport-configs]\n      summary: Delete a sport config\n      responses:\n        '200': { description: OK }\n        '404': { $ref: '#/components/responses/NotFound' }\n\n  # ----------------------------------------------------------------\n  # scoring — match-code gated\n  # ----------------------------------------------------------------\n  /scoring/{fixtureId}/start:\n    parameters:\n      - $ref: '#/components/parameters/FixtureIdPath'\n    post:\n      tags: [scoring]\n      security: [{ matchToken: [] }]\n      summary: Mark scoring underway (scheduled → live)\n      responses:\n        '200':\n          description: OK — includes derived score\n          content:\n            application/json:\n              schema: { $ref: '#/components/schemas/DerivedResponse' }\n        '401': { $ref: '#/components/responses/Unauthorized' }\n        '403': { $ref: '#/components/responses/Forbidden' }\n        '404': { $ref: '#/components/responses/NotFound' }\n        '409': { $ref: '#/components/responses/Conflict' }\n\n  /scoring/{fixtureId}/events:\n    parameters:\n      - $ref: '#/components/parameters/FixtureIdPath'\n    post:\n      tags: [scoring]\n      security: [{ matchToken: [] }]\n      summary: Record a match event (score, foul, card, timeout, note)\n      description: |\n        Client supplies the event UUID; server does\n        `insert ... on conflict (id) do nothing`. Response echoes the\n        `inserted` flag so an optimistic client can distinguish a\n        genuine write from a replay. Also flips `fixtures.status='live'`\n        on the first accepted event and upserts `fixture_live_state`.\n      requestBody:\n        required: true\n        content:\n          application/json:\n            schema: { $ref: '#/components/schemas/RecordEventBody' }\n      responses:\n        '201':\n          description: Created (new event inserted)\n          content:\n            application/json:\n              schema: { $ref: '#/components/schemas/RecordEventResponse' }\n        '200':\n          description: OK (replay — event id already existed)\n          content:\n            application/json:\n              schema: { $ref: '#/components/schemas/RecordEventResponse' }\n        '400': { $ref: '#/components/responses/BadRequest' }\n        '401': { $ref: '#/components/responses/Unauthorized' }\n        '403': { $ref: '#/components/responses/Forbidden' }\n        '404': { $ref: '#/components/responses/NotFound' }\n        '409': { $ref: '#/components/responses/Conflict' }\n\n  /scoring/{fixtureId}/undo:\n    parameters:\n      - $ref: '#/components/parameters/FixtureIdPath'\n    post:\n      tags: [scoring]\n      security: [{ matchToken: [] }]\n      summary: Soft-void a specific match event\n      requestBody:\n        required: true\n        content:\n          application/json:\n            schema:\n              type: object\n              required: [event_id]\n              properties:\n                event_id: { type: string, format: uuid }\n      responses:\n        '200':\n          description: OK\n          content:\n            application/json:\n              schema: { $ref: '#/components/schemas/DerivedResponse' }\n        '400': { $ref: '#/components/responses/BadRequest' }\n        '403': { $ref: '#/components/responses/Forbidden' }\n        '404': { $ref: '#/components/responses/NotFound' }\n\n  /scoring/{fixtureId}/period:\n    parameters:\n      - $ref: '#/components/parameters/FixtureIdPath'\n    post:\n      tags: [scoring]\n      security: [{ matchToken: [] }]\n      summary: Record period_start / period_end\n      requestBody:\n        required: true\n        content:\n          application/json:\n            schema:\n              type: object\n              required: [intent, period]\n              properties:\n                intent:\n                  type: string\n                  enum: [start, end]\n                period:\n                  type: integer\n                  minimum: 1\n                match_clock_ms:\n                  type: integer\n                  minimum: 0\n      responses:\n        '200':\n          description: OK\n          content:\n            application/json:\n              schema: { $ref: '#/components/schemas/DerivedResponse' }\n        '400': { $ref: '#/components/responses/BadRequest' }\n        '409':\n          description: |\n            Ending a period that never opened (or already ended), or\n            trying to change period boundaries on a completed/cancelled\n            fixture.\n\n  /scoring/{fixtureId}/finalize:\n    parameters:\n      - $ref: '#/components/parameters/FixtureIdPath'\n    post:\n      tags: [scoring]\n      security: [{ matchToken: [] }]\n      summary: Snapshot results and set fixtures.status='complete'\n      requestBody:\n        required: false\n        content:\n          application/json:\n            schema:\n              type: object\n              properties:\n                decided_by:\n                  type: string\n                  enum: [normal, penalties, forfeit]\n                  default: normal\n                reopen:\n                  type: boolean\n                  default: false\n                  description: Required true to re-finalize an already-complete fixture.\n      responses:\n        '200':\n          description: OK\n          content:\n            application/json:\n              schema: { $ref: '#/components/schemas/FinalizeResponse' }\n        '400': { $ref: '#/components/responses/BadRequest' }\n        '409':\n          description: Fixture already complete without reopen=true, or cancelled.\n\n  # ----------------------------------------------------------------\n  # match-access — mint / revoke / list operator codes\n  # ----------------------------------------------------------------\n  /match-access:\n    get:\n      tags: [match-access]\n      summary: List operator codes for a fixture\n      description: |\n        Never returns the raw code or its hash — only metadata plus a\n        derived `active` boolean.\n      parameters:\n        - name: fixture\n          in: query\n          required: true\n          schema: { type: string, format: uuid }\n      responses:\n        '200':\n          description: OK\n          content:\n            application/json:\n              schema:\n                type: object\n                properties:\n                  codes:\n                    type: array\n                    items: { $ref: '#/components/schemas/MatchAccessRow' }\n        '400': { $ref: '#/components/responses/BadRequest' }\n        '401': { $ref: '#/components/responses/Unauthorized' }\n    post:\n      tags: [match-access]\n      summary: Mint a scoped operator match code\n      description: |\n        The raw `code` is returned **exactly once** in this response and\n        NEVER again. Store it somewhere the operator can copy immediately\n        (an on-screen modal, an SMS, etc.). The DB keeps only its SHA-256\n        hash.\n      requestBody:\n        required: true\n        content:\n          application/json:\n            schema:\n              type: object\n              required: [fixture_id]\n              properties:\n                fixture_id: { type: string, format: uuid }\n                ttl_minutes:\n                  type: integer\n                  minimum: 15\n                  maximum: 720\n                  default: 240\n                label:\n                  type: string\n                  maxLength: 80\n                  description: Free-form hint (e.g. \"Sam, sideline\")\n      responses:\n        '201':\n          description: Created — code emitted once, never again.\n          content:\n            application/json:\n              schema:\n                type: object\n                required: [id, fixture_id, code, expires_at]\n                properties:\n                  id: { type: string, format: uuid }\n                  fixture_id: { type: string, format: uuid }\n                  code:\n                    type: string\n                    description: 8-character bearer secret. Return to caller once.\n                  expires_at: { type: string, format: date-time }\n                  label: { type: string, nullable: true }\n        '400': { $ref: '#/components/responses/BadRequest' }\n        '401': { $ref: '#/components/responses/Unauthorized' }\n        '404': { $ref: '#/components/responses/NotFound' }\n        '409':\n          description: Fixture is complete or cancelled.\n\n  /match-access/{id}/revoke:\n    parameters:\n      - $ref: '#/components/parameters/UuidPath'\n    post:\n      tags: [match-access]\n      summary: Revoke an operator code (idempotent)\n      responses:\n        '200':\n          description: OK\n          content:\n            application/json:\n              schema:\n                type: object\n                properties:\n                  id: { type: string, format: uuid }\n                  revoked_at: { type: string, format: date-time }\n                  already_revoked: { type: boolean }\n        '400': { $ref: '#/components/responses/BadRequest' }\n        '401': { $ref: '#/components/responses/Unauthorized' }\n        '404': { $ref: '#/components/responses/NotFound' }\n\n  # ----------------------------------------------------------------\n  # live\n  # ----------------------------------------------------------------\n  /live/{fixtureId}:\n    parameters:\n      - $ref: '#/components/parameters/FixtureIdPath'\n    get:\n      tags: [live]\n      security: []\n      summary: Current live summary for one fixture\n      description: |\n        Reads `fixture_live_state`. When no projection row exists yet\n        (fixture never scored), synthesises a zero-scored summary from\n        the fixture row. Response includes a `realtime` object with the\n        subscription parameters for the Supabase Realtime channel — see\n        `docs/realtime.md` for the client-side protocol.\n      responses:\n        '200':\n          description: OK\n          content:\n            application/json:\n              schema: { $ref: '#/components/schemas/LiveSummary' }\n        '400': { $ref: '#/components/responses/BadRequest' }\n        '404': { $ref: '#/components/responses/NotFound' }\n\n  /live:\n    get:\n      tags: [live]\n      security: []\n      summary: Live summaries for every fixture in a published event\n      parameters:\n        - name: event\n          in: query\n          required: true\n          schema: { type: string, format: uuid }\n      responses:\n        '200':\n          description: OK\n          content:\n            application/json:\n              schema:\n                type: object\n                properties:\n                  event: { type: string, format: uuid }\n                  fixtures:\n                    type: array\n                    items: { $ref: '#/components/schemas/LiveSummary' }\n        '400': { $ref: '#/components/responses/BadRequest' }\n        '404': { $ref: '#/components/responses/NotFound' }\n\n  # ----------------------------------------------------------------\n  # standings\n  # ----------------------------------------------------------------\n  /standings:\n    get:\n      tags: [standings]\n      security: []\n      summary: Public standings for a season, grouped by sport\n      parameters:\n        - name: season\n          in: query\n          required: true\n          schema: { type: string, format: uuid }\n        - name: sport\n          in: query\n          required: false\n          schema: { type: string }\n      responses:\n        '200':\n          description: OK\n          content:\n            application/json:\n              schema:\n                oneOf:\n                  - type: object\n                    properties:\n                      season: { type: string, format: uuid }\n                      standings_by_sport:\n                        type: object\n                        additionalProperties:\n                          type: array\n                          items: { $ref: '#/components/schemas/StandingsRow' }\n                  - type: object\n                    properties:\n                      season: { type: string, format: uuid }\n                      sport: { type: string }\n                      standings:\n                        type: array\n                        items: { $ref: '#/components/schemas/StandingsRow' }\n        '400': { $ref: '#/components/responses/BadRequest' }\n        '404': { $ref: '#/components/responses/NotFound' }\n\n  # ----------------------------------------------------------------\n  # results-public\n  # ----------------------------------------------------------------\n  /results-public:\n    get:\n      tags: [results-public]\n      security: []\n      summary: Archive of past events + results\n      description: |\n        Two shapes:\n          - `?season=<uuid>[&limit=][&before=YYYY-MM-DD]` — paginated\n            list, newest-first. `next_before` in the response is the\n            cursor to pass on the next call, or null if this is the\n            last page.\n          - `?event=<uuid>` — one event's results.\n      parameters:\n        - name: season\n          in: query\n          required: false\n          schema: { type: string, format: uuid }\n        - name: event\n          in: query\n          required: false\n          schema: { type: string, format: uuid }\n        - name: limit\n          in: query\n          required: false\n          schema:\n            type: integer\n            minimum: 1\n            maximum: 50\n            default: 10\n        - name: before\n          in: query\n          required: false\n          schema: { type: string, format: date }\n      responses:\n        '200':\n          description: OK\n          content:\n            application/json:\n              schema:\n                oneOf:\n                  - type: object\n                    properties:\n                      season: { type: string, format: uuid }\n                      events:\n                        type: array\n                        items: { $ref: '#/components/schemas/ArchivedEvent' }\n                      next_before:\n                        type: string\n                        format: date\n                        nullable: true\n                  - type: object\n                    properties:\n                      event: { $ref: '#/components/schemas/ArchivedEvent' }\n        '400': { $ref: '#/components/responses/BadRequest' }\n        '404': { $ref: '#/components/responses/NotFound' }\n\n  # ----------------------------------------------------------------\n  # api-docs\n  # ----------------------------------------------------------------\n  /api-docs:\n    get:\n      tags: [docs]\n      security: []\n      summary: Interactive Swagger UI\n      responses:\n        '200':\n          description: HTML page rendering this spec.\n          content:\n            text/html: { schema: { type: string } }\n\n  /api-docs/openapi.yaml:\n    get:\n      tags: [docs]\n      security: []\n      summary: The OpenAPI document itself\n      responses:\n        '200':\n          description: This YAML document.\n          content:\n            application/yaml: { schema: { type: string } }\n\n# ==================================================================\ncomponents:\n  securitySchemes:\n    organiserBearer:\n      type: http\n      scheme: bearer\n      bearerFormat: JWT\n      description: |\n        Supabase Auth JWT for organiser writes (seasons, teams,\n        match-access, sport-configs).\n    matchToken:\n      type: http\n      scheme: bearer\n      description: |\n        Operator match code. Bearer value is the 8-character opaque code\n        returned by `POST /match-access` (case-insensitive; dashes /\n        whitespace are stripped). The server hashes and looks it up in\n        `match_access`; missing / expired / revoked codes 401, and a\n        valid code minted for a different fixture 403s. See ADR 0002.\n\n  parameters:\n    UuidPath:\n      name: id\n      in: path\n      required: true\n      schema: { type: string, format: uuid }\n    FixtureIdPath:\n      name: fixtureId\n      in: path\n      required: true\n      schema: { type: string, format: uuid }\n\n  responses:\n    BadRequest:\n      description: Invalid or malformed request.\n      content:\n        application/json:\n          schema: { $ref: '#/components/schemas/Error' }\n    Unauthorized:\n      description: Missing / invalid credentials.\n      content:\n        application/json:\n          schema: { $ref: '#/components/schemas/Error' }\n    Forbidden:\n      description: Credentials valid but not for this resource.\n      content:\n        application/json:\n          schema: { $ref: '#/components/schemas/Error' }\n    NotFound:\n      description: Resource not found.\n      content:\n        application/json:\n          schema: { $ref: '#/components/schemas/Error' }\n    Conflict:\n      description: Request contradicts current server state.\n      content:\n        application/json:\n          schema: { $ref: '#/components/schemas/Error' }\n\n  schemas:\n    Error:\n      type: object\n      required: [error]\n      properties:\n        error: { type: string }\n\n    Season:\n      type: object\n      properties:\n        id: { type: string, format: uuid }\n        name: { type: string }\n        sports:\n          type: array\n          items: { type: string }\n        starts_on: { type: string, format: date }\n        ends_on: { type: string, format: date }\n        is_active: { type: boolean }\n        is_archived: { type: boolean }\n        created_at: { type: string, format: date-time }\n        updated_at: { type: string, format: date-time }\n\n    CreateSeasonBody:\n      type: object\n      required: [name, sports, starts_on, ends_on]\n      properties:\n        name: { type: string }\n        sports:\n          type: array\n          items: { type: string }\n          minItems: 1\n        starts_on: { type: string, format: date }\n        ends_on: { type: string, format: date }\n        is_active: { type: boolean, default: false }\n\n    UpdateSeasonBody:\n      type: object\n      properties:\n        name: { type: string }\n        sports:\n          type: array\n          items: { type: string }\n          minItems: 1\n        starts_on: { type: string, format: date }\n        ends_on: { type: string, format: date }\n\n    Team:\n      type: object\n      properties:\n        id: { type: string, format: uuid }\n        season_id: { type: string, format: uuid }\n        name: { type: string }\n        created_at: { type: string, format: date-time }\n\n    CreateTeamBody:\n      type: object\n      required: [season_id, name]\n      properties:\n        season_id: { type: string, format: uuid }\n        name: { type: string }\n\n    Event:\n      type: object\n      properties:\n        id: { type: string, format: uuid }\n        event_date: { type: string, format: date }\n        is_published: { type: boolean }\n        seasons:\n          type: object\n          properties:\n            name: { type: string }\n\n    PublicFixture:\n      type: object\n      properties:\n        id: { type: string, format: uuid }\n        sport: { type: string }\n        status:\n          type: string\n          enum: [scheduled, live, complete, cancelled]\n        slot:\n          type: object\n          nullable: true\n          properties:\n            slot_number: { type: integer }\n            starts_at: { type: string }\n            pitch: { type: string, nullable: true }\n        home_team_name: { type: string, nullable: true }\n        away_team_name: { type: string, nullable: true }\n        score:\n          type: object\n          nullable: true\n          description: Present for `live` / `complete` fixtures only.\n          properties:\n            home: { type: integer, minimum: 0 }\n            away: { type: integer, minimum: 0 }\n\n    RecordEventBody:\n      type: object\n      required: [id, type]\n      properties:\n        id: { type: string, format: uuid }\n        type:\n          type: string\n          enum: [score, foul, card, timeout, note]\n        team_id:\n          type: string\n          format: uuid\n          nullable: true\n        player_id:\n          type: string\n          format: uuid\n          nullable: true\n        value:\n          type: integer\n          minimum: 1\n          nullable: true\n        period:\n          type: integer\n          minimum: 0\n          nullable: true\n        match_clock_ms:\n          type: integer\n          minimum: 0\n          nullable: true\n\n    DerivedScore:\n      type: object\n      required: [home, away, foulsByTeam, currentPeriod]\n      properties:\n        home: { type: integer, minimum: 0 }\n        away: { type: integer, minimum: 0 }\n        foulsByTeam:\n          type: object\n          additionalProperties: { type: integer, minimum: 0 }\n        currentPeriod:\n          type: integer\n          nullable: true\n\n    DerivedResponse:\n      type: object\n      required: [fixture_id, fixture_status, derived]\n      properties:\n        fixture_id: { type: string, format: uuid }\n        fixture_status:\n          type: string\n          enum: [scheduled, live, complete, cancelled]\n        derived: { $ref: '#/components/schemas/DerivedScore' }\n\n    RecordEventResponse:\n      allOf:\n        - $ref: '#/components/schemas/DerivedResponse'\n        - type: object\n          required: [event_id, inserted]\n          properties:\n            event_id: { type: string, format: uuid }\n            inserted: { type: boolean }\n\n    PeriodBreakdown:\n      type: object\n      required: [period, home, away]\n      properties:\n        period: { type: integer, minimum: 1 }\n        home: { type: integer, minimum: 0 }\n        away: { type: integer, minimum: 0 }\n\n    FinalizeResponse:\n      allOf:\n        - $ref: '#/components/schemas/DerivedResponse'\n        - type: object\n          required: [result]\n          properties:\n            result:\n              type: object\n              required: [home_score, away_score, periods, decided_by]\n              properties:\n                home_score: { type: integer, minimum: 0 }\n                away_score: { type: integer, minimum: 0 }\n                periods:\n                  type: array\n                  items: { $ref: '#/components/schemas/PeriodBreakdown' }\n                decided_by:\n                  type: string\n                  enum: [normal, penalties, forfeit]\n\n    StandingsRow:\n      type: object\n      properties:\n        team_id: { type: string, format: uuid }\n        team_name: { type: string }\n        played: { type: integer }\n        won: { type: integer }\n        drawn: { type: integer }\n        lost: { type: integer }\n        for: { type: integer }\n        against: { type: integer }\n        goal_diff: { type: integer }\n        points: { type: integer }\n\n    SportConfig:\n      type: object\n      description: Free-form sport configuration.\n      properties:\n        periods:\n          type: object\n          properties:\n            count: { type: integer, minimum: 1 }\n            minutes: { type: integer, minimum: 1 }\n            direction: { type: string, enum: [up, down] }\n        score_increments:\n          type: array\n          items: { type: integer, minimum: 1 }\n          minItems: 1\n        track_fouls: { type: boolean }\n        standings:\n          type: object\n          properties:\n            points:\n              type: object\n              properties:\n                win: { type: integer, minimum: 0 }\n                draw: { type: integer, minimum: 0 }\n                loss: { type: integer, minimum: 0 }\n            tiebreakers:\n              type: array\n              items: { type: string }\n\n    SportConfigRow:\n      type: object\n      properties:\n        id: { type: string, format: uuid }\n        season_id: { type: string, format: uuid }\n        sport: { type: string }\n        config: { $ref: '#/components/schemas/SportConfig' }\n        created_at: { type: string, format: date-time }\n        updated_at: { type: string, format: date-time }\n\n    UpsertSportConfigBody:\n      type: object\n      required: [season_id, sport, config]\n      properties:\n        season_id: { type: string, format: uuid }\n        sport: { type: string }\n        config: { $ref: '#/components/schemas/SportConfig' }\n\n    MatchAccessRow:\n      type: object\n      properties:\n        id: { type: string, format: uuid }\n        fixture_id: { type: string, format: uuid }\n        label: { type: string, nullable: true }\n        expires_at: { type: string, format: date-time }\n        revoked_at: { type: string, format: date-time, nullable: true }\n        last_used_at: { type: string, format: date-time, nullable: true }\n        active: { type: boolean }\n\n    LiveSummary:\n      type: object\n      required: [fixture_id, sport, status, home, fouls, current_period, last_event_at, realtime]\n      properties:\n        fixture_id: { type: string, format: uuid }\n        sport: { type: string }\n        status:\n          type: string\n          enum: [scheduled, live, complete, cancelled]\n        home:\n          type: object\n          properties:\n            team_id: { type: string, format: uuid }\n            name: { type: string }\n            score: { type: integer, minimum: 0 }\n        away:\n          type: object\n          nullable: true\n          properties:\n            team_id: { type: string, format: uuid }\n            name: { type: string }\n            score: { type: integer, minimum: 0 }\n        fouls:\n          type: object\n          additionalProperties: { type: integer, minimum: 0 }\n        current_period:\n          type: integer\n          nullable: true\n        last_event_at:\n          type: string\n          format: date-time\n          nullable: true\n        realtime:\n          type: object\n          required: [channel, table, filter]\n          properties:\n            channel: { type: string }\n            table: { type: string }\n            filter: { type: string }\n\n    ArchivedEvent:\n      type: object\n      properties:\n        id: { type: string, format: uuid }\n        event_date: { type: string, format: date }\n        season_name: { type: string, nullable: true }\n        fixtures:\n          type: array\n          items:\n            type: object\n            properties:\n              id: { type: string, format: uuid }\n              sport: { type: string }\n              home_team_name: { type: string, nullable: true }\n              away_team_name: { type: string, nullable: true }\n              home_score: { type: integer }\n              away_score: { type: integer }\n              periods:\n                type: array\n                items: { $ref: '#/components/schemas/PeriodBreakdown' }\n              decided_by: { type: string }\n              confirmed_at: { type: string, format: date-time }\n";
